# Grid world example
grid = [[0, 2, 4], [1, "X", 6], [3, 5, 7]]

def get_valid_states(grid):
    # Find all valid states (non-goal cells) in the grid
    return [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] != "X" and (i, j) != (2, 2)]

def get_adjacent_states(state):
    # Get all adjacent valid states to a given state
    rows, cols = len(grid), len(grid[0])
    x, y = state
    adjacent = []
    for dx in [-1, 0, 1]:
        for dy in [-1, 0, 1]:
            nx, ny = x + dx, y + dy
            if (nx >= 0 and nx < rows) and (ny >= 0 and ny < cols):
                adjacent.append((nx, ny))
    return [s for s in adjacent if grid[s[0]][s[1]] != "X"]

def get_grouped_states(grid):
    # Get all grouped states from the grid world
    start_state = (0, 0)
    valid_states = get_valid_states(grid)

    # Group states using BFS traversal from each valid state
    grouped_states = {}
    for state in valid_states:
        visited = set()
        queue = [(state, [state])]

        while queue:
            curr_state, path = queue.pop(0)

            if curr_state not in visited:
                visited.add(curr_state)

                if grid[curr_state[0]][curr_state[1]] == "X":
                    grouped_states[" ".join(map(str, state)) + " => " + " ".join(map(str, curr_state))] = path

        # Also include the start state to group it with its neighbors
        visited = set()
        queue = [(start_state, [start_state])]

        while queue:
            curr_state, path = queue.pop(0)

            if curr_state not in visited:
                visited.add(curr_state)

                if grid[curr_state[0]][curr_state[1]] != "X":
                    grouped_states[" ".join(map(str, start_state)) + " => " + " ".join(map(str, curr_state))] = path

    return list(grouped_states.keys())

# Get the grouped states
grouped_states = get_grouped_states(grid)

